export function mapTuplesToCandles(tuples: RawCandleTuple[]): CandlestickData[] {
  return tuples.map(([time, open, high, low, close, volume]) => ({
    time,
    open,
    high,
    low,
    close,
    volume,
  }));
}

export const HISTORICAL_DAILY_CANDLES: CandlestickData[] = mapTuplesToCandles(RAW_HISTORICAL_DAILY);
export const HISTORICAL_WEEKLY_CANDLES: CandlestickData[] = mapTuplesToCandles(RAW_HISTORICAL_WEEKLY);

